// Filter to PNG files and pick the best version for black shirts.
// _W.png = white ink for dark shirts (preferred)
// plain C###.png = colorful designs that work on any shirt
// Exclude _B.png (black ink for light shirts)

const allFiles = $input.all().map(i => i.json);
const pngs = allFiles.filter(f => f.name && f.name.endsWith('.png'));

// Group by design number
const byDesign = {};
for (const f of pngs) {
  const match = f.name.match(/^(C\d+)/);
  if (!match) continue;
  const designId = match[1];
  if (!byDesign[designId]) byDesign[designId] = [];
  byDesign[designId].push(f);
}

// For each design, pick the best file for black shirts
const results = [];
for (const [designId, files] of Object.entries(byDesign)) {
  // Prefer _W variant (white ink for dark shirts)
  let pick = files.find(f => f.name.includes('_W'));
  // Fall back to plain (no _B or _W suffix)
  if (!pick) {
    pick = files.find(f => f.name === `${designId}.png`);
  }
  // Skip if only _B variant exists (black ink = bad on black shirt)
  if (!pick) continue;

  results.push({
    json: {
      designId,
      fileName: pick.name,
      fileId: pick.id,
      mimeType: pick.mimeType,
      retryCount: 0
    }
  });
}

// Sort by design ID
results.sort((a, b) => a.json.designId.localeCompare(b.json.designId, undefined, { numeric: true }));

return results;

