const item = $input.first();
const s = item.json.scene;

const prompt = `Vertical 9:16 realistic photo. Wide shot of ${s.setting}. A man is in the mid-distance with his back mostly to the camera, wearing a plain black t-shirt with no visible design on the back, black baseball cap, grey sweatpants, and black sneakers. He is ${s.prop}. ${s.bystander}. A few other people are scattered around casually. The camera is low, around waist height, with ${s.foreground}. The shot is slightly off-center and tilted, candid and unplanned, as if someone is secretly taking a photo on their phone. Generous headroom above for text overlay. ${s.lighting}, slightly noisy phone camera quality. Do not make it look staged or posed.`;

return [{
  json: {
    ...item.json,
    startFramePrompt: prompt
  },
  binary: item.binary
}];

const response = $input.first().json;
const src = $('Pick Random Scene').first().json;

let imageData = null;
let imageUrl = null;

if (response.data && response.data.length > 0) {
  imageData = response.data[0].b64_json || null;
  imageUrl = response.data[0].url || null;
}

if (!imageData && !imageUrl) {
  throw new Error('Start frame generation returned no image data');
}

const output = {
  json: {
    ...src,
    startFrame_b64: imageData,
    startFrame_url: imageUrl
  }
};

// Create binary for the start frame
if (imageData) {
  output.binary = {
    startFrame: {
      data: imageData,
      mimeType: 'image/png',
      fileName: `${src.designId}_start_frame.png`
    }
  };
} else if (imageUrl) {
  // We'll need to download from URL - store for next step
  output.json.startFrame_needs_download = true;
}

// Carry forward the design binary
const designBinary = $('Download Design PNG').first().binary;
if (designBinary && designBinary.data) {
  if (!output.binary) output.binary = {};
  output.binary.design = designBinary.data;
}

return [output];

const item = $input.first();
const s = item.json.scene;

const prompt = `Using the first reference image as the scene and character reference: generate the SAME man, SAME setting, SAME lighting, SAME camera angle height — but now he has turned and is facing toward the camera at a diagonal angle. He is NOT looking directly at the camera. He has a slight knowing smirk on his face. The front of his black t-shirt now displays the EXACT design from the second reference image — reproduce the design precisely as shown, centered on the chest area of the shirt. Same outfit: black baseball cap, grey sweatpants, black sneakers. Same ${s.prop}. Same candid phone camera quality. Generous headroom above for text overlay. Vertical 9:16 format. Do not change the setting, do not change the person, do not change the lighting.`;

return [{
  json: {
    ...item.json,
    endFramePrompt: prompt
  },
  binary: item.binary
}];

const response = $input.first().json;
const src = $('Build End Frame Prompt').first().json;

let imageData = null;
let imageUrl = null;

if (response.data && response.data.length > 0) {
  imageData = response.data[0].b64_json || null;
  imageUrl = response.data[0].url || null;
}

if (!imageData && !imageUrl) {
  throw new Error('End frame generation returned no image data');
}

const output = {
  json: {
    ...src,
    endFrame_b64: imageData,
    endFrame_url: imageUrl
  }
};

// Create binary for the end frame
if (imageData) {
  output.binary = {
    endFrame: {
      data: imageData,
      mimeType: 'image/png',
      fileName: `${src.designId}_end_frame.png`
    }
  };
}

// Carry forward start frame binary
const prevBinary = $('Parse Start Frame').first().binary;
if (prevBinary) {
  if (!output.binary) output.binary = {};
  if (prevBinary.startFrame) output.binary.startFrame = prevBinary.startFrame;
  if (prevBinary.design) output.binary.design = prevBinary.design;
}

return [output];

// Build the GPT-4o vision payload to compare start and end frames.
const item = $input.first();
const binary = item.binary || {};

let startB64 = item.json.startFrame_b64;
let endB64 = item.json.endFrame_b64;

// If binary data exists, use it
if (!startB64 && binary.startFrame) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'startFrame');
  startB64 = buf.toString('base64');
}
if (!endB64 && binary.endFrame) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'endFrame');
  endB64 = buf.toString('base64');
}

if (!startB64 || !endB64) {
  throw new Error('Missing image data for consistency check');
}

const requestBody = JSON.stringify({
  model: 'gpt-4o',
  messages: [
    {
      role: 'system',
      content: 'You are a visual consistency checker for AI-generated image pairs. You will receive two images: a START frame and an END frame that will be used to generate a video transition. Check if they are consistent enough to produce a believable video. Return ONLY valid JSON with these fields:\n- consistent (boolean): true if the frames match well enough\n- confidence (number 0-100): how confident you are\n- person_match (boolean): same apparent person (build, skin tone, outfit)\n- setting_match (boolean): same location and background\n- lighting_match (boolean): similar lighting and color temperature\n- issues (array of strings): list any problems found\n\nBe lenient — small differences are OK since video generation will interpolate between frames. Only flag as inconsistent if there are major mismatches that would make a jarring video.'
    },
    {
      role: 'user',
      content: [
        { type: 'text', text: 'START FRAME (person from behind, plain black shirt):' },
        { type: 'image_url', image_url: { url: `data:image/png;base64,${startB64}` } },
        { type: 'text', text: 'END FRAME (same person from front, design on shirt):' },
        { type: 'image_url', image_url: { url: `data:image/png;base64,${endB64}` } }
      ]
    }
  ],
  max_tokens: 500
});

return [{
  json: {
    ...item.json,
    requestBody
  },
  binary: item.binary
}];

const response = $input.first().json;
const src = $('Build Consistency Payload').first().json;
const binary = $('Build Consistency Payload').first().binary;

let checkResult = { consistent: false, issues: ['Failed to parse response'] };

try {
  const content = response.choices[0].message.content;
  // Extract JSON from the response (may be wrapped in markdown code blocks)
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    checkResult = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  checkResult = { consistent: false, issues: [`Parse error: ${e.message}`] };
}

return [{
  json: {
    designId: src.designId,
    fileName: src.fileName,
    fileId: src.fileId,
    scene: src.scene,
    retryCount: src.retryCount || 0,
    consistent: checkResult.consistent === true,
    confidence: checkResult.confidence || 0,
    person_match: checkResult.person_match || false,
    setting_match: checkResult.setting_match || false,
    lighting_match: checkResult.lighting_match || false,
    issues: checkResult.issues || []
  },
  binary: binary
}];

// Capture the created folder ID and carry forward binaries
const folderResult = $input.first().json;
const src = $('Parse Consistency Result').first().json;
const binary = $('Parse Consistency Result').first().binary;

return [{
  json: {
    ...src,
    outputFolderId: folderResult.id
  },
  binary
}];

// Log success and return to loop
const src = $('Capture Folder ID').first().json;
console.log(`SUCCESS: ${src.designId} (${src.scene.name}) — confidence: ${src.confidence}%`);

return [{ json: { designId: src.designId, scene: src.scene.id, status: 'success', confidence: src.confidence } }];

// Consistency check failed — check retry count
const src = $input.first().json;
const retryCount = (src.retryCount || 0) + 1;

if (retryCount >= 3) {
  console.log(`FAILED: ${src.designId} (${src.scene.name}) — gave up after ${retryCount} retries. Issues: ${(src.issues || []).join(', ')}`);
  return [{ json: { designId: src.designId, scene: src.scene.id, status: 'failed', retryCount, issues: src.issues } }];
}

console.log(`RETRY ${retryCount}/3: ${src.designId} (${src.scene.name}) — Issues: ${(src.issues || []).join(', ')}`);

// Pass back to end frame generation with incremented retry count
return [{
  json: {
    ...src,
    retryCount
  },
  binary: $input.first().binary
}];

// Gave up — skip this design and move to next in batch
const src = $input.first().json;
console.log(`SKIPPED: ${src.designId} — max retries reached`);
return [{ json: { designId: src.designId, status: 'skipped', issues: src.issues } }];

